	install-catalog --add /etc/sgml/sgml-docbook-dtd-$1.cat \
		/usr/share/sgml/docbook-sgml-$1/catalog > /dev/null 2>&1

	install-catalog --add /etc/sgml/sgml-docbook-dtd-$1.cat \
		/etc/sgml/sgml-docbook.cat > /dev/null 2>&1
}

